For compact weak solenoids, the intersection of a group chain is naturally related to the fundamental group of the corresponding leaf.
% Source locator: arXiv:1702.03032, p. 17, Definition 5.5 and following paragraph.
\citep[Definition~5.5]{hurder2019}
We use this only as structural comparison: the noncompact congruence case receives a direct group proof. Residual finiteness of the closed surface group follows from the standard theorem that finitely generated linear groups are residually finite.
% Source locator: arXiv:1306.2385v1, p. 1, displayed Malcev theorem and following definition.
\citep[p.~1]{nica2013}

\begin{definition}[period owner]
A periodic point of $M_\infty$ is a coherent point $x=(x_n)$ and a single $T>0$ such that $g^T x_n=x_n$ at every level. A sequence of level-dependent closing times $T_n$ is finite-tower data and is not a period of $x$.
\end{definition}

\begin{theorem}[fixed-prefix escape]\label{thm:prefix}
For every fixed integer $D\geq0$, there is $n_0(g,D)$ such that
\[
E_{n,g}(x_g)=1\pmod{x_g^{D+1}}
\]
for every $n\geq n_0(g,D)$. The same conclusion holds for any fixed finite panel of primitive owners. Finite level-dependent multiplicities and scalar weights cannot create a coefficient below degree $o_n(g)$.
\end{theorem}

\begin{theorem}[lift order, count, and period]\label{thm:lifts}
For a primitive content-one owner $g$ and every $N\geq1$:
\begin{enumerate}[label=(\roman*)]
\item the cover degree is $N^4$;
\item the deck image of $g$ has order $N$;
\item the full preimage of the base geodesic has exactly $N^3$ primitive components; and
\item every component has physical period $N\ell(g)$.
\end{enumerate}
\end{theorem}

\begin{theorem}[four-quadrant law]\label{thm:quadrants}
For each owner and level, the four factors are exactly those in Table~\ref{tab:quadrants}. Only the simultaneous clock and multiplicity renormalization recovers the base factor at every level.
\end{theorem}

\begin{table}[ht]
\centering
\caption{Clock and multiplicity interventions for one owner.}
\label{tab:quadrants}
\begin{tabular}{llll}
\toprule
Quadrant & clock & multiplicity & factor and behavior\\
\midrule
$Q_{00}$ & physical & raw & $(1-x_g^N)^{-N^3}\to1$ coefficientwise\\
$Q_{10}$ & rescaled & raw & $(1-x_g)^{-N^3}$; $[x_g]=N^3$\\
$Q_{01}$ & physical & geometric mean & $(1-x_g^N)^{-1}\to1$ coefficientwise\\
$Q_{11}$ & rescaled & geometric mean & $(1-x_g)^{-1}$ exactly\\
\bottomrule
\end{tabular}
\end{table}

\begin{proposition}[uniqueness within scalar clock/exponent renormalizations]\label{prop:unique-renorm}
Fix $N$ and one owner. Let $c_N>0$ multiply the physical lifted period and let $b_N>0$ multiply the logarithm of the raw $N^3$-component product. If
\[
\left(1-e^{-s c_NN\ell(g)}\right)^{-b_NN^3}
=\left(1-e^{-s\ell(g)}\right)^{-1}
\]
for every sufficiently large real $s$, then
\[
c_N=\frac1N,
\qquad
b_N=\frac1{N^3}.
\]
\end{proposition}
